css:
.sl-gallery-floating-wall { padding: 6rem 0; background-color: var(--smartlearn-card-bg); overflow: hidden; }
.sl-gallery-floating-wall .sl-wall-layout { display: flex; flex-direction: column; gap: 4rem; align-items: center; }
@media (min-width: 992px) { .sl-wall-layout { flex-direction: row; justify-content: space-between; } }
.sl-gallery-floating-wall .sl-wall-content { flex: 1; max-width: 450px; }
.sl-gallery-floating-wall .sl-wall-content .sl-section-title { font-size: 2.5rem; font-weight: 800; color: var(--smartlearn-text); margin-bottom: 1.5rem; line-height: 1.2; }
.sl-gallery-floating-wall .sl-wall-content .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin-bottom: 2rem; line-height: 1.6; }
.sl-gallery-floating-wall .sl-wall-content .sl-btn { display: inline-block; padding: 1rem 2rem; background-color: var(--smartlearn-primary); color: #fff; text-decoration: none; border-radius: 0.5rem; font-weight: 700; transition: background-color 0.2s ease; }
.sl-gallery-floating-wall .sl-wall-content .sl-btn:hover { filter: brightness(1.1); }
.sl-gallery-floating-wall .sl-wall-media { flex: 1; position: relative; width: 100%; max-width: 600px; min-height: 400px; }
.sl-gallery-floating-wall .sl-wall-card { position: absolute; border-radius: 1rem; overflow: hidden; box-shadow: 0 20px 40px rgba(0,0,0,0.1); border: 4px solid var(--smartlearn-card-bg); transition: transform 0.4s ease, box-shadow 0.4s ease; }
.sl-gallery-floating-wall .sl-wall-card img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-floating-wall .sl-wall-main { width: 70%; height: 80%; top: 10%; left: 10%; z-index: 1; }
.sl-gallery-floating-wall .sl-wall-sub1 { width: 40%; height: 40%; top: 0; right: 0; z-index: 2; }
.sl-gallery-floating-wall .sl-wall-sub2 { width: 45%; height: 45%; bottom: 0; right: 10%; z-index: 3; }
.sl-gallery-floating-wall .sl-wall-badge { position: absolute; bottom: 15%; left: 0; z-index: 4; background-color: var(--smartlearn-bg); padding: 1rem 1.5rem; border-radius: 2rem; box-shadow: 0 10px 20px rgba(0,0,0,0.1); display: flex; align-items: center; gap: 0.75rem; border: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.05)); }
.sl-gallery-floating-wall .sl-badge-text { font-weight: 700; color: var(--smartlearn-text); font-size: 0.875rem; }
.sl-gallery-floating-wall .sl-item-play-btn:hover { transform: translate(-50%, -50%) scale(1.1) !important; }
@media (prefers-reduced-motion: no-preference) {
    .sl-gallery-floating-wall .sl-wall-main:hover { transform: translateY(-10px) scale(1.02); z-index: 10; box-shadow: 0 30px 60px rgba(0,0,0,0.15); }
    .sl-gallery-floating-wall .sl-wall-sub1:hover, .sl-gallery-floating-wall .sl-wall-sub2:hover { transform: translateY(-10px) scale(1.05); z-index: 10; box-shadow: 0 30px 60px rgba(0,0,0,0.15); }
}
@media (max-width: 767px) {
    .sl-gallery-floating-wall .sl-wall-media { min-height: auto; position: static; display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
    .sl-gallery-floating-wall .sl-wall-card { position: static; width: 100%; height: 200px; border: none; box-shadow: none; }
    .sl-gallery-floating-wall .sl-wall-main { grid-column: 1 / -1; height: 250px; }
    .sl-gallery-floating-wall .sl-wall-badge { position: static; grid-column: 1 / -1; justify-content: center; }
}

js:
(function() {
    const root = document.querySelector('.sl-gallery-floating-wall');
    if (!root) return;
    const playBtn = root.querySelector('.sl-item-play-btn');
    const mediaArea = root.querySelector('#sl-wall-main-card');
    const poster = root.querySelector('.sl-wall-poster');
    const urlEl = root.querySelector('.sl-item-video-url');

    if(!playBtn || !mediaArea || !urlEl) return;

    playBtn.addEventListener('click', () => {
        if(document.body.classList.contains('sl-editor-mode')) return;
        const videoUrl = urlEl.innerText.trim();
        if(!videoUrl) return;

        poster.style.display = 'none';
        playBtn.style.display = 'none';

        const iframe = document.createElement('iframe');
        iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
        iframe.style.position = 'absolute';
        iframe.style.top = '0';
        iframe.style.left = '0';
        iframe.style.width = '100%';
        iframe.style.height = '100%';
        iframe.style.border = 'none';
        iframe.style.zIndex = '10';
        iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
        iframe.setAttribute('allowfullscreen', 'true');

        mediaArea.appendChild(iframe);
    });
})();
